create table public.music_events (id uuid primary key default gen_random_uuid(), composition_id uuid not null references public.music_compositions(id) on delete cascade, beat_position numeric(10,4) not null check (beat_position >= 0), duration numeric(10,4) not null check (duration > 0), type text not null, value jsonb, event_order integer check (event_order is null or event_order >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());;
